<fieldset><legend>Schema fields</legend><div class="field hint"><span>Name</span><span>Database type</span><span>Nullable</span><span>Unique</span><span>Default</span></div><div id="fields"><div class="field"><input name="fields[0][name]" placeholder="name" required><select name="fields[0][type]"><option>string</option><option>text</option><option>integer</option><option>bigInteger</option><option>boolean</option><option>date</option><option>dateTime</option><option>decimal</option></select><label><input type="checkbox" name="fields[0][nullable]" value="1"> yes</label><label><input type="checkbox" name="fields[0][unique]" value="1"> yes</label><input name="fields[0][default]" placeholder="optional"></div></div><button type="button" id="add">+ Add field</button></fieldset>
