<template id="field"><div class="field"><input placeholder="field name" required><select><option>string</option><option>text</option><option>integer</option><option>bigInteger</option><option>boolean</option><option>date</option><option>dateTime</option><option>decimal</option></select><label><input type="checkbox" value="1"> yes</label><label><input type="checkbox" value="1"> yes</label><input placeholder="optional"></div></template>
<script>let i=1;document.querySelector('#add').onclick=()=>{const n=document.querySelector('#field').content.cloneNode(true),e=n.querySelectorAll('input,select');e[0].name='fields['+i+'][name]';e[1].name='fields['+i+'][type]';e[2].name='fields['+i+'][nullable]';e[3].name='fields['+i+'][unique]';e[4].name='fields['+i+'][default]';document.querySelector('#fields').append(n);i++}</script></body></html>
